import React, { useState, useEffect } from 'react';
import { Sparkles, Music, Play, ShoppingCart, Disc, User, UserPlus, UserCheck } from 'lucide-react';
import NavMobile from './NavMobile';
import Lecteur from './Lecteur';
import './Nouveautes.css';

const BADGE_KEY = 'varim_badge_nouveautes_';
const VISITE_KEY = 'varim_nouveautes_derniere_visite_';

function Nouveautes({ allerVers, utilisateur, handleDeconnexion }) {
  const [musiques, setMusiques] = useState([]);
  const [chargement, setChargement] = useState(true);
  const [pisteActive, setPisteActive] = useState(null);
  const [playlist, setPlaylist] = useState([]);
  const [nouvellesIds, setNouvellesIds] = useState(new Set());
  const [pasAbonne, setPasAbonne] = useState(false);

  useEffect(() => {
    if (!utilisateur) { allerVers('login'); return; }

    const derniereVisite = localStorage.getItem(VISITE_KEY + utilisateur.id);

    fetch(`/api/musiques/suivis/${utilisateur.id}`)
      .then(res => res.json())
      .then(data => {
        const liste = data.musiques || [];
        setMusiques(liste);

        if (liste.length === 0) setPasAbonne(true);

        // Marquer les nouvelles depuis la dernière visite
        if (derniereVisite && liste.length > 0) {
          const ids = new Set(
            liste
              .filter(m => new Date(m.date_ajout) > new Date(derniereVisite))
              .map(m => m.id)
          );
          setNouvellesIds(ids);
        }

        // Mettre à jour la date de visite et effacer le badge
        localStorage.setItem(VISITE_KEY + utilisateur.id, new Date().toISOString());
        localStorage.removeItem(BADGE_KEY + utilisateur.id);
        window.dispatchEvent(new Event('varim_badge_update'));

        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, [utilisateur]);

  const jouer = (musique) => {
    const singles = musiques.filter(m => m.type === 'single' && m.fichier_url);
    setPlaylist(singles.map(m => ({
      url: m.fichier_url, titre: m.titre, artiste: m.nom_artiste,
      pochette: m.pochette_url, id: m.musique_id || m.id, musiqueId: m.musique_id || m.id
    })));
    setPisteActive({
      url: musique.fichier_url, titre: musique.titre, artiste: musique.nom_artiste,
      pochette: musique.pochette_url, id: musique.musique_id || musique.id,
      musiqueId: musique.musique_id || musique.id
    });
  };

  const dateRelative = (date) => {
    const diff = Date.now() - new Date(date).getTime();
    const jours = Math.floor(diff / 86400000);
    if (jours === 0) return "Aujourd'hui";
    if (jours === 1) return "Hier";
    if (jours < 7) return `Il y a ${jours} jours`;
    if (jours < 30) return `Il y a ${Math.floor(jours / 7)} semaine${Math.floor(jours / 7) > 1 ? 's' : ''}`;
    return `Il y a ${Math.floor(jours / 30)} mois`;
  };

  return (
    <div className="nouv-page">
      <header className="nouv-header">
        <div className="nouv-header-logo" onClick={() => allerVers('accueil')}>
          <img src="/logo.png" alt="Varim Music" className="nouv-logo-img" />
          <span>Varim Music</span>
        </div>
        <NavMobile utilisateur={utilisateur} allerVers={allerVers} handleDeconnexion={handleDeconnexion} />
      </header>

      <div className="nouv-contenu">
        <div className="nouv-titre-wrapper">
          <Sparkles size={20} className="nouv-titre-ic" />
          <div>
            <h1 className="nouv-titre">Nouveautés</h1>
            <p className="nouv-sous-titre">Publications de vos artistes suivis</p>
          </div>
        </div>

        {chargement ? (
          <div className="nouv-chargement">Chargement...</div>
        ) : pasAbonne || musiques.length === 0 ? (
          <div className="nouv-vide">
            <UserPlus size={52} className="nouv-vide-ic" />
            <h2>Aucune nouveauté</h2>
            <p>Suivez des artistes depuis leur page profil pour voir leurs nouvelles publications ici.</p>
            <button className="nouv-btn-catalogue" onClick={() => allerVers('catalogue')}>
              Découvrir des artistes
            </button>
          </div>
        ) : (
          <div className="nouv-liste">
            {musiques.map(m => (
              <div key={m.id} className={`nouv-ligne ${nouvellesIds.has(m.id) ? 'nouvelle' : ''}`}>
                <div className="nouv-pochette" onClick={() => m.type === 'single' ? allerVers('single_' + m.id) : allerVers('album_' + m.id)}>
                  {m.pochette_url
                    ? <img src={m.pochette_url} alt={m.titre} />
                    : <div className="nouv-pochette-vide">{m.type === 'album' ? <Disc size={18} /> : <Music size={18} />}</div>
                  }
                  {nouvellesIds.has(m.id) && <span className="nouv-badge-new">Nouveau</span>}
                </div>

                <div className="nouv-infos">
                  <p className="nouv-info-titre">{m.titre}</p>
                  <p className="nouv-info-artiste" onClick={() => allerVers('profil_' + m.artiste_id)}>
                    <User size={11} /> {m.nom_artiste}
                  </p>
                  <div className="nouv-info-bas">
                    <span className={`nouv-type-badge ${m.type}`}>{m.type}</span>
                    <span className="nouv-date">{dateRelative(m.date_ajout)}</span>
                  </div>
                </div>

                <div className="nouv-actions">
                  {m.type === 'single' && m.fichier_url && (
                    <button className="nouv-btn-play" onClick={() => jouer(m)}>
                      <Play size={16} />
                    </button>
                  )}
                  <button className="nouv-btn-acheter" onClick={() => allerVers('achat_' + m.id)}>
                    <ShoppingCart size={14} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {pisteActive && (
        <Lecteur
          piste={pisteActive}
          playlist={playlist}
          onPisteChange={setPisteActive}
          onFermer={() => { setPisteActive(null); setPlaylist([]); }}
        />
      )}
    </div>
  );
}

export default Nouveautes;
